#include "stm32f4xx.h"

#include <stdint.h>

#include "fpu_init.h"
#include "hcsr04.h"
#include "iwdg.h"
#include "telemetry.h"

#include "FreeRTOS.h"
#include "task.h"
#include "semphr.h"
#include "event_groups.h"
#include "queue.h"


#define SENSOR_TASK_BIT (1 << 0)

EventGroupHandle_t IWDG_eventgroup;
QueueHandle_t Distance_Data_Queue;
QueueHandle_t  Sensor_Payload_Queue;

int main(void){
	FPU_Init();
	HCSR04_Init();
	IWDG_Init();

	IWDG_eventgroup = xEventGroupCreate();
	Distance_Data_Queue = xQueueCreate(5, sizeof(uint32_t));
	Sensor_Payload_Queue = xQueueCreate(5, sizeof(SensorData_t));

	if(IWDG_eventgroup != NULL && Distance_Data_Queue != NULL && Sensor_Payload_Queue != NULL){
		SensorTask_Init();
		WatchDogTask_Init();
	    }

	    vTaskStartScheduler();

	  while(1){}
}

void EXTI1_IRQHandler(void){

	if(EXTI_PR & (1 << 1)){

		EXTI_PR |= (1 << 1);
		if(GPIOA_IDR & (1 << 1)){
			TIM2_CNT = 0;
		}
		else{
			uint32_t pulse_width = TIM2_CNT;

			BaseType_t xHigherPriorityTaskWoken = pdFALSE;
			xQueueSendFromISR(Distance_Data_Queue, &pulse_width , &xHigherPriorityTaskWoken);
			portYIELD_FROM_ISR(xHigherPriorityTaskWoken);
		}
	}

}

void vApplicationStackOverflowHook(TaskHandle_t xTask, char *pcTaskName){

	(void)xTask;
	(void)pcTaskName;


	GPIOA_MODER &= ~(3U << 10);
	GPIOA_MODER |= (1U << 10);

	TIM2_CR1 |= (1 << 0);

	GPIOA_ODR &= ~(1 << 0);
	while(1){
		GPIOA_ODR ^= (1 << 5);

		while(TIM2_CNT <= 1000000){
			__asm("NOP"); // No Operation
		}

		TIM2_CNT = 0;
	}

}
